import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxButton,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    name: string;
    email: string;
    phone: string;
    city: string;
    street: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [city, setCity] = useState('');
  const [street, setStreet] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));
  const goBack = () => setStep((current) => Math.max(current - 1, 0));

  const handleSubmit = () => {
    onSubmit({ name, email, phone, city, street, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '480px',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Имя"
            required
            value={name}
            onChange={(event) => setName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            prefix="+7"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={street}
            onChange={(event) => setStreet(event.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      ) : null}

      {step === 2 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <p style={{ color: 'var(--jx-text-2)' }}>Проверьте введённые данные перед отправкой:</p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            <span>Имя: {name}</span>
            <span>Почта: {email}</span>
            <span>Телефон: {phone}</span>
            <span>Город: {city}</span>
            <span>Адрес: {street}</span>
            <span>Индекс: {postalCode}</span>
          </div>
        </div>
      ) : null}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

